// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address payer, uint256 amount) public {
        vm.assume(payer != address(0));
        amount = bound(amount, 0, type(uint128).max);

        vm.deal(payer, amount);

        uint256 before = c.getBalance(payer);

        vm.prank(payer);
        c.addToBalance{value: amount}();

        uint256 afterBal = c.getBalance(payer);

        assertTrue(afterBal >= before);
    }
}
